input.command:
cd /Volumes/ext1/swe/repos/mc-design-eval/benchmarks/plugin-baseline/runs/build-1/millkit2; cat > parts/stairs.mjs <<'E'
// Part: Stairs. Flights per plan RESERVED: plot 1 x19 z11..15; plot 2 x30 z10..14; plot 4 z15 x57..53.
import { stair_run } from "../vocab.mjs";

export function build(g) {
  stair_run(g, [19, 3, 11], "south", 7, "acacia", 1, { carve: true });
  stair_run(g, [30, 3, 10], "south", 7, "pale_oak", 1, { carve: true });
  stair_run(g, [57, 3, 15], "west", 7, "spruce", 1, { carve: true });
}
E
sed -i 's|\["Stairs and ladders", "parts/stairs.mjs"\]|["Stairs and ladders", "parts/stairs.mjs"]|' build.mjs
./make.sh 2>&1 | grep -iE "stairs|REFUSED|OFF-" ; M=/Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs; node $M walk build.nbt --rooms rooms.json | grep -iE "unreach|partly|stair" ; node $M fit build.nbt --rooms rooms.json | grep -i stair

